import std::cli;
import std::csv;
import std::datetime;
import std::encoding;
import std::utf8;
import std::watchdog;
import std::regex;
import std::reflect;
import std::json;
import std::toml;
import std::image;
import std::sql;
Result<int64, MessageError> readNumber(String text) { let value = std::json::parse(text)?; return Result<int64, MessageError>::Ok(value.asInt().unwrap()); }
void main() {
    { let error = std::cli::cliError("--count", "参数缺失"); assert(error.toString().contains("--count")); }
    { let error = std::csv::csvError(3, 7, "字段错误"); assert(error.line == 3 && error.column == 7); assert(error.toString().contains("字段错误")); }
    { assert((std::datetime::DateTimeError::InvalidDate).toString() != ""); }
    { assert((std::encoding::EncodingError::InvalidCharacter(9)).toString().contains("9")); }
    { assert((std::utf8::Utf8Error::InvalidSequence(12)).toString().contains("12")); }
    { assert((std::watchdog::WatchdogError::InvalidTimeout).toString() != ""); }
    { assert((std::regex::RegexError::Invalid).toString() != ""); }
    { assert((std::reflect::ReflectError::NotFound).toString() != ""); }
    { Result<std::json::JsonValue, MessageError> result = std::json::parse("{bad"); assert(result.isErr()); assert(result.error().toString() != ""); assert(readNumber("42").unwrap() == 42); assert(readNumber("{bad").isErr()); }
    { Result<std::toml::TomlValue, MessageError> result = std::toml::parse("x = ["); assert(result.isErr()); assert(result.error().toString() != ""); }
    { Result<Image, MessageError> result = Image::make(0, 1); assert(result.isErr()); assert(result.error().toString().contains("宽高")); }
    { Query query; query.page(-1); Result<SqlStatement, MessageError> result = query.build(); assert(result.isErr()); assert(result.error().toString().contains("分页")); }
    println("all Error modules OK");
}
